import{_ as t,o as e,c as a,Q as d}from"./chunks/framework.48927342.js";const k=JSON.parse('{"title":"The Rented Car (Il-karozza mikrija)","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/dialogues/08-rented-car.md","filePath":"en/more/maltese/practice/dialogues/08-rented-car.md"}'),r={name:"en/more/maltese/practice/dialogues/08-rented-car.md"},o=d('<h1 id="the-rented-car-il-karozza-mikrija" tabindex="-1">The Rented Car (Il-karozza mikrija) <a class="header-anchor" href="#the-rented-car-il-karozza-mikrija" aria-label="Permalink to &quot;The Rented Car (Il-karozza mikrija)&quot;">​</a></h1><p><strong>Scenario:</strong> Carmen Micallef calls the car-hire company to speak to Mr Martin Deguara. He is not there, so she explains to the employee that she rented a car fifteen days ago and is flying back to her country on Friday; they arrange to return the car at their office in the airport car park before her flight.</p><p><strong>Source:</strong> Djalogu addattat minn Speaking Maltese 2 ta&#39; Charles Daniel Saliba (Dialogue adapted from <em>Speaking Maltese 2</em> by Charles Daniel Saliba)</p><h2 id="complete-dialogue" tabindex="-1">Complete Dialogue <a class="header-anchor" href="#complete-dialogue" aria-label="Permalink to &quot;Complete Dialogue&quot;">​</a></h2><p><strong>Carmen (Customer):</strong> Bonġu, jien Carmen Micallef. Nista&#39; nkellem lis-Sur Martin Deguara, jekk jogħġbok?</p><p><strong>Tal-karozzi (Car-Hire Agent):</strong> Skużani, illum Martin mhux hawn. Nista&#39; naqdik jien?</p><p><strong>Carmen (Customer):</strong> Ma jimpurtax, mela ħa nispjega kollox lilek. Ħmistax ilu kont krejt karozza mingħandkom u issa se nsiefer lura pajjiżi nhar il-Ġimgħa. Nixtieq inkun naf kif se ngħaddilkom il-karozza lura.</p><p><strong>Tal-karozzi (Car-Hire Agent):</strong> Inti x&#39;ħin se ssiefer il-Ġimgħa?</p><p><strong>Carmen (Customer):</strong> It-titjira hija fid-disgħa ta&#39; billejl.</p><p><strong>Tal-karozzi (Car-Hire Agent):</strong> Tajjeb ħafna, mela l-Ġimgħa stess qabel tidħol l-ajruport ejja hawn l-uffiċċju tagħna li jinsab fil-parkeġġ tal-ajruport stess. Ikollna bżonn nispezzjonaw il-karozza u malli jkun kollox sew, nirrilaxxaw il-VISA tiegħek.</p><p><strong>Carmen (Customer):</strong> Ok, naħseb ikunu xi s-sitta ta&#39; flgħaxija kif nasal.</p><p><strong>Tal-karozzi (Car-Hire Agent):</strong> Tajjeb, ikun hawn jien dak il-ħin.</p><p><strong>Carmen (Customer):</strong> Sewwa wisq, mela narak il-Ġimgħa fis-sitta ta&#39; flgħaxija. Grazzi!</p><p><strong>Tal-karozzi (Car-Hire Agent):</strong> Grazzi lilek, saħħa!</p><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><h3 id="_1-carmen-customer" tabindex="-1">1. Carmen (Customer) <a class="header-anchor" href="#_1-carmen-customer" aria-label="Permalink to &quot;1. Carmen (Customer)&quot;">​</a></h3><p><strong>Malti:</strong> Bonġu, jien Carmen Micallef. Nista&#39; nkellem lis-Sur Martin Deguara, jekk jogħġbok?</p><p><strong>Translation:</strong> Good morning, I am Carmen Micallef. Can I speak to Mr Martin Deguara, please?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Bonġu</td><td>good morning</td><td>Formal greeting</td></tr><tr><td>jien</td><td>I</td><td>First-person pronoun</td></tr><tr><td>Carmen Micallef</td><td>Carmen Micallef</td><td>Person&#39;s name</td></tr><tr><td>Nista&#39;</td><td>I can</td><td>First-person singular</td></tr><tr><td>nkellem</td><td>I speak with</td><td>First-person singular of <code>kellem</code></td></tr><tr><td>lis-Sur</td><td>with Mr</td><td>Contracted <code>li</code> + <code>is-Sur</code>; <code>Sur</code> = Mr</td></tr><tr><td>Martin Deguara</td><td>Martin Deguara</td><td>Person&#39;s name</td></tr><tr><td>jekk jogħġbok</td><td>please</td><td>Literally &quot;if it pleases you&quot;</td></tr></tbody></table><h3 id="_2-tal-karozzi-car-hire-agent" tabindex="-1">2. Tal-karozzi (Car-Hire Agent) <a class="header-anchor" href="#_2-tal-karozzi-car-hire-agent" aria-label="Permalink to &quot;2. Tal-karozzi (Car-Hire Agent)&quot;">​</a></h3><p><strong>Malti:</strong> Skużani, illum Martin mhux hawn. Nista&#39; naqdik jien?</p><p><strong>Translation:</strong> Excuse me, Martin is not here today. Can I help you myself?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Skużani</td><td>excuse me</td><td><code>skuża</code> + <code>-ni</code> (me)</td></tr><tr><td>illum</td><td>today</td><td>Time adverb</td></tr><tr><td>mhux</td><td>not</td><td>Negation</td></tr><tr><td>hawn</td><td>here</td><td>Place adverb</td></tr><tr><td>Nista&#39;</td><td>I can</td><td>First-person singular</td></tr><tr><td>naqdik</td><td>I serve you; I help you</td><td><code>naqdi</code> + <code>-k</code> (you)</td></tr><tr><td>jien</td><td>I</td><td>Emphatic &quot;I myself&quot;</td></tr></tbody></table><h3 id="_3-carmen-customer" tabindex="-1">3. Carmen (Customer) <a class="header-anchor" href="#_3-carmen-customer" aria-label="Permalink to &quot;3. Carmen (Customer)&quot;">​</a></h3><p><strong>Malti:</strong> Ma jimpurtax, mela ħa nispjega kollox lilek. Ħmistax ilu kont krejt karozza mingħandkom u issa se nsiefer lura pajjiżi nhar il-Ġimgħa. Nixtieq inkun naf kif se ngħaddilkom il-karozza lura.</p><p><strong>Translation:</strong> Never mind, then I&#39;ll explain everything to you. Fifteen days ago I rented a car from you, and now on Friday I&#39;m flying back to my country. I&#39;d like to know how I can return the car to you.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Ma jimpurtax</td><td>it doesn&#39;t matter</td><td><code>ma</code> + <code>jimpurta</code> + <code>x</code> negation</td></tr><tr><td>mela</td><td>then; so</td><td>Discourse marker</td></tr><tr><td>ħa nispjega</td><td>I&#39;ll explain</td><td><code>ħa</code> (let me) + <code>nispjega</code> (I explain)</td></tr><tr><td>kollox</td><td>everything</td><td>Indefinite pronoun</td></tr><tr><td>lilek</td><td>to you</td><td><code>li</code> + <code>-lek</code></td></tr><tr><td>Ħmistax ilu</td><td>fifteen days ago</td><td><code>ħmistax</code> (fifteen) + <code>ilu</code> (ago)</td></tr><tr><td>kont krejt</td><td>I had rented</td><td><code>kont</code> (past auxiliary) + <code>krejt</code> (loanword <code>rent</code>, first-person past)</td></tr><tr><td>karozza</td><td>car</td><td>Feminine noun</td></tr><tr><td>mingħandkom</td><td>from you</td><td><code>mingħand</code> + <code>-kom</code> (you, plural)</td></tr><tr><td>issa</td><td>now</td><td>Adverb</td></tr><tr><td>se nsiefer</td><td>I will fly</td><td><code>se</code> (future) + <code>nsiefer</code> (I travel / fly)</td></tr><tr><td>lura</td><td>back</td><td>Adverb</td></tr><tr><td>pajjiżi</td><td>my country</td><td><code>pajjiż</code> + <code>-i</code> (my)</td></tr><tr><td>nhar</td><td>on the day of</td><td>Literally &quot;day&quot;</td></tr><tr><td>il-Ġimgħa</td><td>Friday</td><td>With the definite article</td></tr><tr><td>Nixtieq</td><td>I would like</td><td>First-person singular</td></tr><tr><td>inkun naf</td><td>to know</td><td><code>inkun</code> (I be) + <code>naf</code> (I know)</td></tr><tr><td>kif</td><td>how</td><td>Question adverb</td></tr><tr><td>se ngħaddilkom</td><td>I will hand over to you</td><td><code>ngħaddi</code> + <code>-lkom</code> (to you, plural)</td></tr><tr><td>lura</td><td>back; in return</td><td>Here: &quot;return&quot;</td></tr></tbody></table><h3 id="_4-tal-karozzi-car-hire-agent" tabindex="-1">4. Tal-karozzi (Car-Hire Agent) <a class="header-anchor" href="#_4-tal-karozzi-car-hire-agent" aria-label="Permalink to &quot;4. Tal-karozzi (Car-Hire Agent)&quot;">​</a></h3><p><strong>Malti:</strong> Inti x&#39;ħin se ssiefer il-Ġimgħa?</p><p><strong>Translation:</strong> What time are you flying on Friday?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Inti</td><td>you</td><td>Second-person pronoun</td></tr><tr><td>x&#39;ħin</td><td>what time</td><td><code>x&#39;</code> (what) + <code>ħin</code> (time)</td></tr><tr><td>se ssiefer</td><td>you will fly</td><td><code>se</code> + <code>ssiefer</code> (second-person singular)</td></tr><tr><td>il-Ġimgħa</td><td>Friday</td><td>With the definite article</td></tr></tbody></table><h3 id="_5-carmen-customer" tabindex="-1">5. Carmen (Customer) <a class="header-anchor" href="#_5-carmen-customer" aria-label="Permalink to &quot;5. Carmen (Customer)&quot;">​</a></h3><p><strong>Malti:</strong> It-titjira hija fid-disgħa ta&#39; billejl.</p><p><strong>Translation:</strong> The flight is at nine in the evening.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>It-titjira</td><td>the flight</td><td>Feminine noun (loanword)</td></tr><tr><td>hija</td><td>is</td><td>Third-person feminine singular</td></tr><tr><td>fid-disgħa</td><td>at nine</td><td>Contracted <code>f&#39;</code> + <code>id-disgħa</code></td></tr><tr><td>ta&#39; billejl</td><td>in the evening</td><td><code>ta&#39;</code> (of) + <code>billejl</code> (night; standard spelling <code>bil-lejl</code>)</td></tr></tbody></table><h3 id="_6-tal-karozzi-car-hire-agent" tabindex="-1">6. Tal-karozzi (Car-Hire Agent) <a class="header-anchor" href="#_6-tal-karozzi-car-hire-agent" aria-label="Permalink to &quot;6. Tal-karozzi (Car-Hire Agent)&quot;">​</a></h3><p><strong>Malti:</strong> Tajjeb ħafna, mela l-Ġimgħa stess qabel tidħol l-ajruport ejja hawn l-uffiċċju tagħna li jinsab fil-parkeġġ tal-ajruport stess. Ikollna bżonn nispezzjonaw il-karozza u malli jkun kollox sew, nirrilaxxaw il-VISA tiegħek.</p><p><strong>Translation:</strong> Very good, then on Friday itself, before you enter the airport, come to our office, which is in the airport car park itself. We need to inspect the car, and as soon as everything is fine, we&#39;ll release your VISA deposit.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tajjeb ħafna</td><td>very good</td><td><code>tajjeb</code> (good) + <code>ħafna</code> (very)</td></tr><tr><td>l-Ġimgħa stess</td><td>on Friday itself</td><td><code>stess</code> (itself, emphatic)</td></tr><tr><td>qabel</td><td>before</td><td>Preposition</td></tr><tr><td>tidħol</td><td>you enter</td><td>Second-person singular</td></tr><tr><td>l-ajruport</td><td>the airport</td><td>Loanword <code>airport</code></td></tr><tr><td>ejja</td><td>come</td><td>Imperative</td></tr><tr><td>hawn</td><td>here</td><td>Place adverb</td></tr><tr><td>l-uffiċċju</td><td>the office</td><td>Loanword <code>uffiċċju</code></td></tr><tr><td>tagħna</td><td>our</td><td>Possessive</td></tr><tr><td>li jinsab</td><td>which is located</td><td><code>jinsab</code> (is located, third-person singular)</td></tr><tr><td>fil-parkeġġ</td><td>in the car park</td><td>Contracted <code>f&#39;</code> + <code>il-parkeġġ</code></td></tr><tr><td>tal-ajruport stess</td><td>of the airport itself</td><td><code>ta&#39;</code> (of) + <code>ajruport</code> + <code>stess</code></td></tr><tr><td>Ikollna bżonn</td><td>we will need</td><td><code>ikollna</code> (we will have) + <code>bżonn</code> (need)</td></tr><tr><td>nispezzjonaw</td><td>we inspect</td><td>Loanword <code>spezzjona</code></td></tr><tr><td>il-karozza</td><td>the car</td><td>With the definite article</td></tr><tr><td>malli</td><td>as soon as</td><td>Conjunction</td></tr><tr><td>jkun kollox sew</td><td>everything is fine</td><td><code>jkun</code> (is) + <code>kollox</code> (everything) + <code>sew</code> (well)</td></tr><tr><td>nirrilaxxaw</td><td>we release</td><td>Loanword <code>rilaxxa</code></td></tr><tr><td>il-VISA tiegħek</td><td>your VISA deposit</td><td>Car-rental context: releasing the VISA pre-authorisation / deposit</td></tr></tbody></table><h3 id="_7-carmen-customer" tabindex="-1">7. Carmen (Customer) <a class="header-anchor" href="#_7-carmen-customer" aria-label="Permalink to &quot;7. Carmen (Customer)&quot;">​</a></h3><p><strong>Malti:</strong> Ok, naħseb ikunu xi s-sitta ta&#39; flgħaxija kif nasal.</p><p><strong>Translation:</strong> OK, I think it will be around six in the evening when I arrive.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Ok</td><td>OK</td><td>Loanword</td></tr><tr><td>naħseb</td><td>I think</td><td>First-person singular</td></tr><tr><td>ikunu</td><td>will be</td><td>Plural future (referring to the time)</td></tr><tr><td>xi</td><td>about; around</td><td>Adverb</td></tr><tr><td>s-sitta</td><td>six</td><td><code>is-sitta</code> (six)</td></tr><tr><td>ta&#39; flgħaxija</td><td>in the evening</td><td>Printed <code>flgħaxija</code>; standard spelling <code>filgħaxija</code></td></tr><tr><td>kif nasal</td><td>when I arrive</td><td><code>kif</code> (when) + <code>nasal</code> (I arrive, first-person singular)</td></tr></tbody></table><h3 id="_8-tal-karozzi-car-hire-agent" tabindex="-1">8. Tal-karozzi (Car-Hire Agent) <a class="header-anchor" href="#_8-tal-karozzi-car-hire-agent" aria-label="Permalink to &quot;8. Tal-karozzi (Car-Hire Agent)&quot;">​</a></h3><p><strong>Malti:</strong> Tajjeb, ikun hawn jien dak il-ħin.</p><p><strong>Translation:</strong> Fine, I will be here at that time.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tajjeb</td><td>fine</td><td>Adjective</td></tr><tr><td>ikun hawn jien</td><td>I will be here</td><td><code>ikun</code> (will be) + <code>hawn</code> (here) + <code>jien</code> (I)</td></tr><tr><td>dak il-ħin</td><td>at that time</td><td><code>dak</code> (that) + <code>il-ħin</code> (time)</td></tr></tbody></table><h3 id="_9-carmen-customer" tabindex="-1">9. Carmen (Customer) <a class="header-anchor" href="#_9-carmen-customer" aria-label="Permalink to &quot;9. Carmen (Customer)&quot;">​</a></h3><p><strong>Malti:</strong> Sewwa wisq, mela narak il-Ġimgħa fis-sitta ta&#39; flgħaxija. Grazzi!</p><p><strong>Translation:</strong> Excellent, then I&#39;ll see you on Friday at six in the evening. Thank you!</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Sewwa wisq</td><td>excellent</td><td><code>sewwa</code> (correct) + <code>wisq</code> (very)</td></tr><tr><td>mela</td><td>then</td><td>Discourse marker</td></tr><tr><td>narak</td><td>I&#39;ll see you</td><td><code>nara</code> + <code>-k</code> (you)</td></tr><tr><td>il-Ġimgħa</td><td>Friday</td><td>With the definite article</td></tr><tr><td>fis-sitta</td><td>at six</td><td>Contracted <code>f&#39;</code> + <code>is-sitta</code></td></tr><tr><td>ta&#39; flgħaxija</td><td>in the evening</td><td>See above</td></tr><tr><td>Grazzi</td><td>thank you</td><td>Polite expression</td></tr></tbody></table><h3 id="_10-tal-karozzi-car-hire-agent" tabindex="-1">10. Tal-karozzi (Car-Hire Agent) <a class="header-anchor" href="#_10-tal-karozzi-car-hire-agent" aria-label="Permalink to &quot;10. Tal-karozzi (Car-Hire Agent)&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi lilek, saħħa!</p><p><strong>Translation:</strong> Thank you, bye!</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Grazzi lilek</td><td>thank you</td><td><code>grazzi</code> (thanks) + <code>lilek</code> (to you)</td></tr><tr><td>saħħa</td><td>bye; take care</td><td>Literally &quot;health&quot;; common farewell</td></tr></tbody></table>',55),i=[o];function n(l,s,c,h,u,g){return e(),a("div",null,i)}const p=t(r,[["render",n]]);export{k as __pageData,p as default};
